class Solution {
public:
    double largestSumOfAverages(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];

        vector<double> dp(n + 1, -1e18);
        dp[0] = 0.0;

        for (int j = 1; j <= k; j++) {
            for (int i = n; i >= 1; i--) {
                double best = -1e18;
                for (int t = j - 1; t < i; t++) {
                    double avg = (double)(pref[i] - pref[t]) / (double)(i - t);
                    double val = dp[t] + avg;
                    if (val > best) best = val;
                }
                dp[i] = best;
            }
        }
        return dp[n];
    }
};
